  value.PayloadLength = 0;
  value.AimX = 0;
  value.AimY = 0;
  value.AimZ = 0;
  value.Recoil = 0;
  value.Drift = 0;
  value.WideKey = 0n;
  value.Flux = 0n;
  value.Ping = 0;
  value.CrcHint = 0;
